// Funcion de enviar la informacion a la APIDian
function envJson2Api($url, $jsObj, $request)
{
    switch ($request) {
        case 'POST':
            $jsObj = json_encode($jsObj);
            $header = [
                "Accept: application/json",
                "Authorization: Bearer 04cde66691dad4b7aea1729558a0c6f6a1f281ad687c6c92e7d5e32f7f445c0d",
                "Content-Type: application/json"
            ];
            # code...
            break;
        case 'GET':
            $jsObj = '';
            $header = [
                "Accept-Encoding: gzip, deflate",
                "Connection: keep-alive",
                "Content-Type: application/json",
                "X-CSRF-TOKEN: ",
                "accept: application/json",
                "cache-control: no-cache"
            ];
            # code...
            break;
        case 'PUT':
            $jsObj = json_encode($jsObj);
            $header = [
                "Accept-Encoding: gzip, deflate",
                "Authorization: Bearer 04cde66691dad4b7aea1729558a0c6f6a1f281ad687c6c92e7d5e32f7f445c0d",
                "Connection: keep-alive",
                "Content-Type: application/json",
                "X-CSRF-TOKEN: ",
                "accept: application/json",
                "cache-control: no-cache"
            ];
            # code...
            break;

        default:
            # code...
            break;
    }
    $curl = curl_init();
    curl_setopt_array($curl, [
        CURLOPT_URL => $url,
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_ENCODING => "",
        CURLOPT_MAXREDIRS => 10,
        CURLOPT_TIMEOUT => 30,
        CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
        CURLOPT_CUSTOMREQUEST => $request,
        CURLOPT_POSTFIELDS => $jsObj,
        CURLOPT_HTTPHEADER => $header,
    ]);
    $response = curl_exec($curl);
    $err = curl_error($curl);
    curl_close($curl);
    if ($err) echo __LINE__, " cURL Error #: ", $err, "\r\n";
    else echo __LINE__, json_encode($response), "\r\n";
    echo "\r\n";
}
